import json, os, glob

def analyze_session(path):
    tools = []
    with open(path) as f:
        for line in f:
            try:
                d = json.loads(line)
                if d.get('role') == 'assistant':
                    content = d.get('content', [])
                    if isinstance(content, list):
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'toolCall':
                                name = c.get('name','?')
                                args = c.get('arguments',{})
                                if name == 'read':
                                    tools.append(f"read({args.get('path','?')})")
                                elif name == 'bash':
                                    cmd = args.get('command','')[:100]
                                    tools.append(f'bash({cmd})')
                                elif name == 'agents':
                                    act = args.get('action','?')
                                    tgt = args.get('agent','')
                                    tools.append(f'agents({act}, {tgt})')
                                elif name == 'finish':
                                    tools.append(f"finish({args.get('status','?')})")
                                elif name == 'write':
                                    tools.append(f"write({args.get('path','?')})")
                                elif name == 'edit':
                                    tools.append(f"edit({args.get('path','?')})")
                                elif name == 'workflow':
                                    tools.append(f"workflow({args.get('action','?')}, {args.get('name','')})")
                                elif name == 'checkpoint':
                                    tools.append(f"checkpoint()")
                                else:
                                    tools.append(f'{name}(...)')
            except json.JSONDecodeError:
                pass
    return tools

# Analyze all sessions in the last 13 hours (since 05:00 UTC)
# Focus on coach, qa, bob - the agents most likely doing repetitive work
agents_data = {}
dirs = sorted(glob.glob('.state/sessions/history/s_17741[6-9]*') + glob.glob('.state/sessions/history/s_177420*'))

for d in dirs:
    meta_path = os.path.join(d, 'meta.json')
    session_path = os.path.join(d, 'session.jsonl')
    if not os.path.exists(meta_path) or not os.path.exists(session_path):
        continue
    with open(meta_path) as f:
        meta = json.load(f)
